  "audit.validationTitle": "AI 审计验证",
  "audit.validationPrompt": "以下是项目文档（docs/ 文件夹）。遵循严格的 4 阶段验证协议。在完成所有 4 个阶段前，不要发出 KRONN:VALIDATION_COMPLETE。\n\n## 阶段 1 — 自动修复（自主）\n阅读源代码并修复可修复的内容：孤立的 TODO 标记、骨架文件、过时信息。直接更新 docs/ 文件。\n\n## 阶段 2 — 模糊问题（交互式）\n逐个提问。每次回答后，在下一个问题前更新 docs/ 文件。如果答案揭示新未知项，提出后续问题。\n\n## 阶段 3 — 技术债务审查（交互式）\n审查 docs/inconsistencies-tech-debt.md 和 docs/tech-debt/ 中的每一项。对于每个项目：评估是否准确？优先级如何？是否应创建工单？\n\n## 阶段 4 — 文档挑战（交互式）\n向我提出 2-3 个新开发人员会问的实际问题。检查文档是否回答了这些问题。如果不足，更新并提出另一个问题。\n\n仅当所有 4 个阶段完成后，以 \"KRONN:VALIDATION_COMPLETE\" 结束。",
