  "settings.ahExplainEnforce": "拒绝伪造的 `[src:]` 引用。在审核期间，步骤会重试（最多 3 次）然后干净失败，而不是写入包含虚构引用的文档；在讨论中，包含伪造引用的回复将保留但标记为需修正。",
