  "settings.gcModeAlways": "始终注入",
  "settings.gcModeNoProject": "仅无项目",
  "settings.gcModeNever": "已禁用",
  "tour.welcome.title": "欢迎使用 Kronn！",
  "tour.demoRender.title": "预览生成的页面",
  "tour.demoRender.desc": "前次对话生成的 HTML 页面在 Kronn 的原生预览中显示。您可点击右上角按钮放大查看。",
  "tour.demoRender.info": "此演示对话已本地预加载。游览结束后，它将保留在您的存档中。",
  "tour.demoExports.title": "无需单个 token 即可导出 PDF 和 DOCX",
  "tour.demoExports.desc": "导出由 Kronn 生成，而非模型：将此页面转换为 PDF 或 DOCX（可多次转换）无需消耗 token。仅初始内容需付费（当代理生成时）。",
  "tour.discHeader.title": "引导对话",
  "tour.discHeader.desc": "标题栏选择主代理并显示已加入的 CLI 会话（如存在）。计划打开任务，Git 显示已更改文件，设置调整此对话的上下文。",
  "tour.discHeader.agentNote": "CLI 代理：通过 kronn-internal MCP，它们可加入此对话，通过 ID 检索消息，按关键词搜索，回复并维护计划，无需复制完整历史。",
  "tour.agentsConfig.title": "您的代理，需先启用",
  "tour.agentsConfig.desc": "代理是 Kronn 启动以回复和处理文件的 AI 助手。常规对话需启用至少一个；其模型和连接在卡片上配置。无代理对话仍可被已加入的 CLI 会话使用。",
  "tour.navigation.title": "在 Kronn 中导航",
  "tour.navigation.desc": "在此找到项目、代理对话、规划、能力插件、自动化和设置。可随时返回。",
  "tour.mentions.title": "与一个或多个代理对话",
  "tour.mentions.desc": "无提及时，仅主代理回复。@提及目标其他代理或已加入的 CLI 会话；@全部向所有列出的参与者发送消息，可能触发多个回复。您还可附加文件以提供有用上下文。",
  "tour.copyableIds.title": "一键复制 ID",
  "tour.copyableIds.desc": "消息、对话、任务、快速提示、快速 API、工作流及其他对象均有可复制 ID。在另一对话中引用此 ID，而非复制整页或丢失上下文。",
  "tour.copyableIds.agentNote": "通过 kronn-internal MCP，代理解析 ID 并首先加载匹配的最小上下文。若请求仍不明确，可加载所需邻近消息或详情。",
  "tour.globalSearch.title": "查找任意消息，无论位置",
  "tour.globalSearch.desc": "高级搜索扫描所有对话中每条消息的内容。此处 Kronn 搜索了演示消息中的短语，直接找到匹配对话。",
  "tour.navPlanning.title": "共享计划",
  "tour.navPlanning.desc": "每个对话可拥有任务列表。规划汇集所有列表，以便按优先级排序工作并由代理更新，无需重读对话。",
  "tour.navPlanning.agentNote": "CLI 代理：通过 kronn-internal MCP，它们按需加载紧凑计划，可读取、创建、更新或优先级排序任务（当请求明确时）。否则，提出变更供审批。",
  "tour.contextHelp.title": "帮助触手可及",
  "tour.contextHelp.desc": "您可在对话及项目、规划、插件和自动化空间中找到此按钮。它解释屏幕背后的模型，无需重播整个游览。",
  "tour.taskOrchestration.title": "委派任务，同时保持控制",
  "tour.taskOrchestration.desc": "从讨论计划打开任务并选择“使用代理运行”。Kronn 为 worker 创建子讨论和隔离的 worktree；父讨论跟踪工作，并在任何受保护的集成前审查交付。",
  "tour.welcome.desc": "5 到 7 分钟内，您将掌握如何引导 AI 代理、其工具和自动化。按 Esc 键退出；可稍后继续。",
  "tour.conceptProject.title": "您的项目",
  "tour.conceptProject.desc": "项目代表您机器上的工作文件夹。它汇集了代理所需的代码、文档和设置。",
  "tour.conceptProject.agentNote": "CLI 代理：通过复制 ID，kronn-internal MCP 可识别项目并过滤其关联任务。代码和文档仍从 CLI 打开的仓库读取。",
  "tour.newProject.title": "添加项目",
  "tour.newProject.desc": "此按钮用于添加现有文件夹或创建新项目。",
  "tour.addPlugin.title": "添加插件",
  "tour.addPlugin.desc": "插件为代理添加功能。它可暴露 MCP 服务器、API 或 CLI 工具，混合插件可跨多个接口复用配置。API 代理调用保持认证在服务端；MCP 同步可能将所需变量写入 CLI 的本地配置。",
  "tour.addPlugin.agentNote": "CLI 代理：kronn-internal MCP 列出已配置插件，并通过代理调用其声明的 API 端点，不向模型暴露 API 密钥。MCP 工具由 CLI 单独提供。",
  "tour.sidebar.title": "您的对话",
  "tour.sidebar.desc": "对话按项目组织。自动创建的对话分组以保持列表整洁。",
  "tour.newDisc.title": "开始对话",
  "tour.newDisc.desc": "点击打开表单。您将选择回复代理、提供上下文的项目，以及必要时的技能（专业指令）或文件。",
  "tour.discForm.title": "表单",
  "tour.discForm.desc": "选择代理、项目、文件及必要时的技能（专业指令）以启动对话。",
  "tour.discForm.agentNote": "通过 kronn-internal MCP，CLI 代理可创建或打开对话，按需读取其消息。",
  "tour.navAutomation.title": "自动化",
  "tour.navAutomation.desc": "自动化将重复操作转化为可靠、可重用的资源，可与代理共享。",
  "tour.automationLibrary.title": "统一的自动化库",
  "tour.automationLibrary.desc": "侧边栏统一展示工作流、Quick API、Quick Prompt 和 Quick Exec（CLI）。可搜索或按项目筛选；选择资源后，其详情会在主面板打开，Quick API、Prompt 和 Exec 会直接进入编辑状态。",
  "tour.automationQuickPrompt.title": "快速提示：重用指令",
  "tour.automationQuickPrompt.desc": "快速提示保存与代理绑定的提示，可一键运行、监控执行并提供动态变量。您也可从对话中启动；动态变量稍后将添加至该对话。",
  "tour.automationQuickApi.title": "快速 API：无需启动模型调用",
  "tour.automationQuickApi.desc": "快速 API 保存配置 API 的调用。直接运行不启动模型：提取数据、发送消息或触发服务无需代理。此方式拆分操作可使结果更快、更确定、更高效。",
  "tour.automationQuickExec.title": "Quick Exec：复用 CLI 命令",
  "tour.automationQuickExec.desc": "Quick Exec 使用受控参数运行二进制程序，无需 shell 或模型，并将输出规范化为 JSON、CSV、文本或行。它适合在工作流中复用 AWS、Fastly 或 GitHub 等 CLI，并可直接测试。",
  "tour.automationWorkflow.title": "工作流：编排每一步",
  "tour.automationWorkflow.desc": "工作流串联 Quick API、Quick Exec、代理和机械步骤。例如：通过 API 或 CLI 无模型采集数据，将推理交给代理，确定性生成 HTML 页面并发布。它也可按计划执行或等待审批。",
  "tour.automationActions.title": "创建或导入",
  "tour.automationActions.desc": "面板操作会适配当前类别：可使用 AI 或手动创建，也可导入现有定义。",
  "tour.automationAi.title": "或委托初稿",
  "tour.automationAi.desc": "AI 创建会打开专用对话：代理与您共同设计结构，Kronn 将结果保存为可复用的工作流、Quick API、Quick Prompt 或 Quick Exec。",
  "tour.automationAi.agentNote": "通过 kronn-internal MCP 和已配置插件，代理可查看、创建、更新和运行工作流、Quick API、Quick Prompt 和 Quick Exec。AI 可帮助您减少对 AI 的依赖。",
  "tour.done.title": "您已准备就绪！",
  "tour.done.desc": "若无活动代理，前往设置启动。否则，启动首个对话。？按钮可重播游览，设置也允许您从断点继续。",
  "tour.done.agentNote": "通过 kronn-internal MCP，CLI 代理可解析复制 ID、按需读取对话、维护计划，并管理快速提示、快速 API 和工作流。已配置 API 通过代理调用。",
