  "mcp.drift.sometimes": "对 `{1}` 的 {0} 次调用失败（{2}），但也有成功的 —— 端点存在，是声明的参数不匹配。",
  "mcp.custom.helper.sys.verify": "先验证再断言 —— API 文档常常有误：参数名过时、端点已删除、分页未记录。凭空编造的规格会让代理白白浪费数小时。如果你能执行命令且用户已提供凭据，请在声明每个端点之前用真实调用（curl）测试它，未见其响应的端点一律不要声明。三个陷阱：(1) 未知参数常被接受并被静默忽略 —— 200 并不能证明过滤器生效，请把响应中的判别字段与你的请求做比对；(2) 当响应分页或被包装（`{data:[…], meta}`）时，在描述中记录其结构以及真正有效的参数名；(3) 若单条记录很大，请标注出来，以便代理只投影所需字段。凡是无法验证的，请在描述前加 `❔ 未验证：` —— 绝不要断言。",
  "mcp.custom.helper.sys.style": "保持简洁。如需澄清，请一次问一个问题。始终注明完成配置所需内容。",
