  "mcp.scope": "作用域",
  "mcp.help.mcp-fastly": "Kronn 已包含 Fastly CLI 和官方 MCP 服务器。\n\n建议使用本地认证：\n   fastly auth login\n   fastly auth list\n\n也可在下方保存加密的 FASTLY_API_TOKEN。如果本地 CLI 无法提供令牌，Kronn 会将其作为备用。",
  "mcp.help.mcp-gitlab": "需要 GitLab CLI (glab)。\n\n建议使用本地认证：\n   glab auth login\n   glab auth status\n\nKronn 会复用此会话来运行 MCP 和检测仓库。可将下方字段留空，或保存加密的 GITLAB_TOKEN（需 api 范围的 PAT）作为备用。对于自托管实例，还需在 GITLAB_HOST 中输入完整 URL。",
  "mcp.help.api-microsoft-365": "通过 Microsoft Graph API 连接 Microsoft 365（Outlook、Teams、OneDrive），复用 Azure CLI 凭据，不存储令牌。\n\n安装 Azure CLI（跨平台）：\n- macOS：brew install azure-cli\n- Windows：winget install Microsoft.AzureCLI\n- Linux：curl -sL https://aka.ms/InstallAzureCLIDeb | sudo bash（Debian/Ubuntu）\n- 所有系统：https://aka.ms/installazurecli\n\n然后执行一次：az login（使用组织的 SSO/broker，可满足不允许纯设备代码登录的条件访问策略）。\n\n验证：az account get-access-token --resource https://graph.microsoft.com\n\nKronn 会通过 CLI 在内存中即时获取 Graph 令牌；设置和生成的配置中都不会保存令牌。",
