  "wiz.starter.testCoverage": "测试覆盖率审计",
  "wiz.starter.testCoveragePrompt": "分析项目结构，识别缺乏测试的关键文件和函数：\n- 无集成测试的API端点\n- 无单元测试的工具函数\n- 有交互但无测试的UI组件\n\n生成优先级列表，列出最重要的缺失测试，并为每项提供测试模板。",
  "wiz.starter.docUpdate": "文档更新",
